// TeamCity's Parallel Tests feature writes the tests a batch must not run to the file named by this
// system property. System properties are available to build steps through TEAMCITY_BUILD_PROPERTIES_FILE.
// See https://www.jetbrains.com/help/teamcity/parallel-tests.html
const (
	buildPropertiesFileEnv = "TEAMCITY_BUILD_PROPERTIES_FILE"
	excludesFileProperty   = "teamcity.build.parallelTests.excludesFile"
)

// parallelTestsExcludesFile returns the exclusions file for this batch, or "" when the build is not batched.
func parallelTestsExcludesFile() (string, error) {
	propertiesFile := os.Getenv(buildPropertiesFileEnv)
	if propertiesFile == "" {
		return "", nil
	}
	properties, err := readProperties(propertiesFile)
	if err != nil {
		return "", fmt.Errorf("reading TeamCity build properties %s: %w", propertiesFile, err)
	}
	return properties[excludesFileProperty], nil
}

// readProperties parses the simple key=value Java properties files written by TeamCity.
func readProperties(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	properties := map[string]string{}
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || line[0] == '#' || line[0] == '!' {
			continue
		}
		key, value := splitProperty(line)
		properties[unescapeProperty(key)] = unescapeProperty(value)
	}
	return properties, scanner.Err()
}

func splitProperty(line string) (string, string) {
	for i := 0; i < len(line); i++ {
		switch line[i] {
		case '\\':
			i++
		case '=', ':':
			return strings.TrimSpace(line[:i]), strings.TrimSpace(line[i+1:])
		}
	}
	return line, ""
}

func unescapeProperty(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] != '\\' || i+1 == len(s) {
			b.WriteByte(s[i])
			continue
		}
		i++
		switch s[i] {
		case 't':
			b.WriteByte('\t')
		case 'n':
			b.WriteByte('\n')
		case 'r':
			b.WriteByte('\r')
		case 'f':
			b.WriteByte('\f')
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

// readExclusions reads one test name per line, ignoring blank lines and # comments.
func readExclusions(path string) (map[string]bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	excluded := map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			excluded[line] = true
		}
	}
	return excluded, nil
}

// batchTests removes the tests TeamCity assigned to other batches.
func batchTests(testNames []string) ([]string, error) {
	excludesFile, err := parallelTestsExcludesFile()
	if err != nil || excludesFile == "" {
		return testNames, err
	}
	excluded, err := readExclusions(excludesFile)
	if err != nil {
		return nil, fmt.Errorf("reading Parallel Tests exclusions %s: %w", excludesFile, err)
	}
	batch := make([]string, 0, len(testNames))
	for _, name := range testNames {
		if !excluded[name] {
			batch = append(batch, name)
		}
	}
	fmt.Printf("Parallel Tests: running %d of %d tests in this batch (%d excluded by %s)\n", len(batch), len(testNames), len(testNames)-len(batch), excludesFile)
	return batch, nil
}
